var BRAND = {name: 'Escale', domain: 'escale-bassin.fr', tagline: 'Le livret d’accueil qui connaît le Bassin', contact: ''};  /* contact : e-mail qui reçoit les demandes Signature */

/* ---------- Couleurs ---------- */
function hex2rgb(h){ h = String(h || '#000').replace('#', ''); if (h.length === 3) h = h.replace(/./g, '$&$&'); var n = parseInt(h, 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }
function rgb2hex(r){ return '#' + r.map(function(v){ v = Math.max(0, Math.min(255, Math.round(v))); return (v < 16 ? '0' : '') + v.toString(16); }).join(''); }
function mix(a, b, t){ var x = hex2rgb(a), y = hex2rgb(b); return rgb2hex([0, 1, 2].map(function(i){ return x[i] + (y[i] - x[i]) * t; })); }
function rgba(h, a){ var c = hex2rgb(h); return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
function lum(h){ var c = hex2rgb(h).map(function(v){ v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); }); return .2126 * c[0] + .7152 * c[1] + .0722 * c[2]; }
function contrast(a, b){ var x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }
function hsl(h){ var c = hex2rgb(h).map(function(v){ return v / 255; }), mx = Math.max.apply(0, c), mn = Math.min.apply(0, c), l = (mx + mn) / 2, s = 0, hh = 0, d = mx - mn;
  if (d){ s = l > .5 ? d / (2 - mx - mn) : d / (mx + mn); hh = mx === c[0] ? (c[1] - c[2]) / d + (c[1] < c[2] ? 6 : 0) : mx === c[1] ? (c[2] - c[0]) / d + 2 : (c[0] - c[1]) / d + 4; hh *= 60; }
  return [hh, s, l]; }
function fromHsl(h, s, l){ var f = function(n){ var k = (n + h / 30) % 12, a = s * Math.min(l, 1 - l); return 255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))); }; return rgb2hex([f(0), f(8), f(4)]); }
/* Ajuste une couleur d'accent pour qu'elle reste lisible sur un fond donné */
function readableOn(acc, bg, min){ min = min || 3.2; var h = hsl(acc), dark = lum(bg) < .3, l = h[2], i = 0, c = acc;
  while (contrast(c, bg) < min && i++ < 40){ l += dark ? .02 : -.02; if (l <= 0 || l >= 1) break; c = fromHsl(h[0], h[1], l); }
  return c; }

