/* Temps de trajet estimé (ligne droite × détour) */
function travel(m, lang){
  var r = m * 1.3, en = lang === 'en';
  if (r < 1500) return {mode: 'walk', min: Math.max(2, Math.round(r / 1000 * 12)), txt: Math.max(2, Math.round(r / 1000 * 12)) + (en ? ' min walk' : ' min à pied'), e: '🚶'};
  if (r < 9000) return {mode: 'bike', min: Math.round(r / 1000 * 4), txt: Math.round(r / 1000 * 4) + (en ? ' min by bike' : ' min à vélo'), e: '🚲'};
  var mn = Math.round(r / 1000 * 1.6 + 4); return {mode: 'car', min: mn, txt: mn + (en ? ' min drive' : ' min en voiture'), e: '🚗'};
}
function mapsLink(name, lat, lon){ return 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(lat != null ? lat + ',' + lon : name); }
function mapsDir(lat, lon, mode){ return 'https://www.google.com/maps/dir/?api=1&destination=' + lat + ',' + lon + '&travelmode=' + ({walk: 'walking', bike: 'bicycling', car: 'driving'}[mode] || 'driving'); }
