/* ---------- Horaires OpenStreetMap (sous-ensemble courant) ---------- */
var OH_D = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'], OH_M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
