    rule = rule.trim(); if (!rule || /^(PH|SH)\b/.test(rule)) return;
    var mm = rule.match(/^((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(?: \d{1,2})?(?:-(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(?: \d{1,2})?)?)\s*/);
    if (mm){
      var rg = mm[1].split('-'), a = rg[0].split(' '), b = (rg[1] || rg[0]).split(' ');
      var am = OH_M.indexOf(a[0]), bm = OH_M.indexOf(b[0]), ad = +(a[1] || 1), bd = +(b[1] || 31), cur = mo * 100 + day, s0 = am * 100 + ad, s1 = bm * 100 + bd;
      var inside = s0 <= s1 ? (cur >= s0 && cur <= s1) : (cur >= s0 || cur <= s1);
      if (!inside) return;
      rule = rule.slice(mm[0].length);
    }
    var dm = rule.match(/^((?:Mo|Tu|We|Th|Fr|Sa|Su)(?:-(?:Mo|Tu|We|Th|Fr|Sa|Su))?(?:,(?:Mo|Tu|We|Th|Fr|Sa|Su)(?:-(?:Mo|Tu|We|Th|Fr|Sa|Su))?)*)\s*/), days = [0, 1, 2, 3, 4, 5, 6];
    if (dm){
      days = []; dm[1].split(',').forEach(function(seg){ var q = seg.split('-'), x = OH_D.indexOf(q[0]), y = OH_D.indexOf(q[1] || q[0]); for (var i = 0; i < 7; i++){ var k = (x + i) % 7; days.push(k); if (k === y) break; } });
      rule = rule.slice(dm[0].length);
    } else if (/^[A-Za-z]/.test(rule) && !/^(off|closed)/.test(rule)) return;
    parsed = true;
    if (days.indexOf(dow) < 0) return;
