    var tr = [], re = /(\d{1,2}):(\d{2})-(\d{1,2}):(\d{2})/g, t;
    while ((t = re.exec(rule))) tr.push([+t[1] * 60 + +t[2], +t[3] * 60 + +t[4] || 1440]);
    if (tr.length) res = {open: tr.some(function(r){ return mins >= r[0] && mins < r[1]; }), ranges: tr, known: true, today: true};
