/* ---------- Heure de Paris ---------- */
var _pf = null;
function parisParts(t){
  _pf = _pf || new Intl.DateTimeFormat('en-GB', {timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short', hour12: false});
  var o = {}; _pf.formatToParts(new Date(t)).forEach(function(p){ o[p.type] = p.value; });
  return {y: +o.year, m: +o.month, d: +o.day, h: +o.hour % 24, mi: +o.minute, dow: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(o.weekday)};
}
function paris(y, m, d, h, mi){ var g = Date.UTC(y, m - 1, d, h, mi), p = parisParts(g), back = Date.UTC(p.y, p.m - 1, p.d, p.h, p.mi); return g - (back - g); }
function parseLocal(s){ var a = s.split(/[-T:]/).map(Number); return paris(a[0], a[1], a[2], a[3] || 0, a[4] || 0); }
function hhmm(t, lang){ var p = parisParts(t); return lang === 'en' ? (p.h < 10 ? '0' : '') + p.h + ':' + (p.mi < 10 ? '0' : '') + p.mi : p.h + 'h' + (p.mi < 10 ? '0' : '') + p.mi; }
