/* =========================================================
   Agenda du Bassin : fêtes et manifestations publiées par les offices de tourisme
   (DATAtourisme, Licence Ouverte). AGENDA = {at, src, ot, ev:[{n, c, la, lo, a, k, p, d, u, s, i, o, r}]} est inséré par build.py ;
   s = fiche de l'événement chez l'office, i = sa photo (hébergée chez la source), o = l'office qui l'a publié ;
   p = périodes [[AAAAMMJJ, AAAAMMJJ], …], r = 1 pour ce qui dure (expositions, visites régulières, marchés).
   ========================================================= */
var AG_CATS = {
  fete: {fr: 'Fêtes & traditions', en: 'Festivals & traditions', e: '🎉', lx: 'star', w: 3},
  scene: {fr: 'Concerts & spectacles', en: 'Concerts & shows', e: '🎵', lx: 'music', w: 3},
  marche: {fr: 'Marchés & brocantes', en: 'Markets & fairs', e: '🧺', lx: 'basket', w: 2},
  expo: {fr: 'Expositions', en: 'Exhibitions', e: '🖼️', lx: 'frame', w: 2},
  sport: {fr: 'Sport & nature', en: 'Sport & outdoors', e: '🌿', lx: 'leaf', w: 1.5},
  famille: {fr: 'En famille', en: 'For families', e: '🧸', lx: 'heart', w: 1.5},
  visite: {fr: 'Visites & balades', en: 'Tours & walks', e: '🧭', lx: 'compass', w: 1.5},
  autre: {fr: 'Animations', en: 'Events', e: '📅', lx: 'calendar', w: 1}
};
function agDay(off){ var p = parisParts(Date.now()); return agAdd(p.y * 10000 + p.m * 100 + p.d, off || 0); }
function agDate(d){ return new Date(Date.UTC(Math.floor(d / 10000), Math.floor(d / 100) % 100 - 1, d % 100, 12)); }
function agAdd(d, n){ var x = agDate(d); x.setUTCDate(x.getUTCDate() + n); return x.getUTCFullYear() * 10000 + (x.getUTCMonth() + 1) * 100 + x.getUTCDate(); }
function agDow(d){ return agDate(d).getUTCDay(); }
function agFromISO(s){ var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || ''); return m ? +(m[1] + m[2] + m[3]) : 0; }
function agFmt(d, lang, o){ return agDate(d).toLocaleDateString(lang === 'en' ? 'en-GB' : 'fr-FR', Object.assign({weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC'}, o || {})); }
function agShort(d, lang){ var x = agDate(d), L = lang === 'en' ? 'en-GB' : 'fr-FR'; return {dow: x.toLocaleDateString(L, {weekday: 'short', timeZone: 'UTC'}).replace('.', ''), d: x.getUTCDate(), m: x.toLocaleDateString(L, {month: 'short', timeZone: 'UTC'}).replace('.', '')}; }
/* Fenêtres : aujourd'hui, demain, ce week-end, 7 jours, 30 jours */
function agWindow(k){
  var t = agDay(), w = agDow(t);
  if (k === 'today') return [t, t];
  if (k === 'tomorrow') return [agAdd(t, 1), agAdd(t, 1)];
  if (k === 'weekend'){ if (w === 0) return [t, t]; if (w === 6) return [t, agAdd(t, 1)]; return [agAdd(t, 6 - w), agAdd(t, 7 - w)]; }
  if (k === 'month') return [t, agAdd(t, 30)];
  return [t, agAdd(t, 6)];
}
/* Prochain jour où l'événement a lieu dans [from, to], ou 0 */
function agNext(ev, from, to){ var best = 0; (ev.p || []).forEach(function(p){ if (p[1] < from || p[0] > to) return; var d = Math.max(p[0], from); if (!best || d < best) best = d; }); return best; }
function agCount(ev, from){ return (ev.p || []).filter(function(p){ return p[1] >= from; }).length; }
/* Événements autour d'un point : o = {lat, lon, km, from, to, cat, ongoing, extra} */
function agQuery(o){
  var list = (typeof AGENDA !== 'undefined' && AGENDA.ev ? AGENDA.ev : []).concat(o.extra || []), out = [];
  list.forEach(function(ev){
    if (!!ev.r !== !!o.ongoing && !ev.mine) return;
    if (o.cat && o.cat !== 'all' && (ev.k || []).indexOf(o.cat) < 0) return;
    var dist = ev.la != null ? distM(o.lat, o.lon, ev.la, ev.lo) : 0;
    if (!ev.mine && dist > o.km * 1000) return;
    var day = agNext(ev, o.from, o.to); if (!day) return;
    out.push({ev: ev, day: day, dist: dist});
  });
  return out.sort(function(a, b){ return a.day - b.day || (b.ev.mine ? 1 : 0) - (a.ev.mine ? 1 : 0) || a.dist - b.dist; });
}
/* Les plus beaux rendez-vous d'une période, près du logement : one-shots, week-end, lien d'info, photo, proximité,
   et ce qui plaît à ces voyageurs-là (profil choisi dans le livret) */
var AG_PROF = {famille: {famille: 2.5, fete: .6, marche: .3}, couple: {scene: .7, expo: .7, visite: .4, famille: -2.5}, amis: {scene: .9, fete: .9, sport: .5, famille: -2.5}, solo: {expo: .7, visite: .7, sport: .4, famille: -2.5}};
function agScore(x, t, prof){
  var w = agDow(x.day), cat = AG_CATS[(x.ev.k || ['autre'])[0]] || AG_CATS.autre, p = x.ev.p || [], span = p.length === 1 ? (agDate(p[0][1]) - agDate(p[0][0])) / 864e5 : 0;
  var P = prof && AG_PROF[prof.g], fit = P ? Math.max.apply(null, (x.ev.k || ['autre']).map(function(k){ return P[k] || 0; })) : 0;
  if (P && (x.ev.k || []).some(function(k){ return P[k] < 0; })) fit = Math.min(fit, -2.5);
  return (x.ev.mine ? 6 : cat.w) + fit + (w === 0 || w === 5 || w === 6 ? 1 : 0) + (x.ev.s || x.ev.u ? .5 : 0) + (x.ev.i ? .4 : 0) - (span > 3 ? 1.5 : 0) - (p.length > 3 ? .8 : 0) - x.dist / 8000 - .15 * ((agDate(x.day) - agDate(t)) / 864e5);
}
function agBest(o, n){
  var t = agDay(), seen = {};
  return agQuery(o).map(function(x){ x.score = agScore(x, t, o.prof); return x; }).sort(function(a, b){ return b.score - a.score; })
    .filter(function(x){ var k = x.ev.n.toLowerCase(); if (seen[k]) return false; seen[k] = 1; return true; }).slice(0, n || 3).sort(function(a, b){ return a.day - b.day; });
}
/* À la une : les 7 prochains jours */
function agHighlights(o, n){ var t = agDay(); return agBest(Object.assign({}, o, {from: t, to: agAdd(t, 6)}), n); }
/* Rendez-vous ajoutés par l'hôte → même format que l'agenda */
function agMine(cfg){ return ((cfg.agenda && cfg.agenda.mine) || []).filter(function(m){ return m.n && m.d1; }).map(function(m){ var a = agFromISO(m.d1), b = agFromISO(m.d2) || a; return {n: m.n, c: m.w || '', d: m.note || '', h: m.h || '', k: ['fete'], p: [[a, Math.max(a, b)]], mine: 1, u: m.u || ''}; }); }
function agOn(cfg){ return typeof AGENDA !== 'undefined' && !!(AGENDA.ev && AGENDA.ev.length) && !(cfg.agenda && cfg.agenda.on === false); }
function agKm(cfg){ return +(cfg.agenda && cfg.agenda.km) || 25; }
/* Où en savoir plus : la fiche de l'événement chez sa source, sinon le site de l'organisateur, sinon l'agenda de l'office de tourisme */
function agOffice(ev){ return (typeof AGENDA !== 'undefined' && AGENDA.ot && ev.o && AGENDA.ot[ev.o]) || null; }
function agLink(ev){ var ot = agOffice(ev), ok = function(u){ return /^https?:\/\//.test(u || ''); };
  if (ok(ev.s)) return {href: ev.s, kind: 'page', ot: ot};
  if (ok(ev.u)) return {href: ev.u, kind: 'org', ot: ot};
  if (ot && ok(ot.a)) return {href: ot.a, kind: 'agenda', ot: ot};
  return null; }
function agHost(u){ var m = /^https?:\/\/(?:www\.)?([^\/?#]+)/.exec(u || ''); return m ? m[1].toLowerCase() : ''; }
function agUpdated(lang){ var d = agFromISO(AGENDA.at); return d ? agFmt(d, lang, {weekday: undefined}) : ''; }

