var BASSIN_FOR = {'ares': 'cabanes', 'andernos-les-bains': 'cabanes', 'lege-cap-ferret': 'ocean', 'arcachon': 'arguin', 'la-teste-de-buch': 'arguin', 'gujan-mestras': 'cabanes', 'le-teich': 'passes', 'biganos': 'passes', 'audenge': 'passes', 'lanton': 'cabanes', 'le-porge': 'dune'};
var PALETTE_FOR = {'lege-cap-ferret': 'marine', 'la-teste-de-buch': 'sable', 'le-porge': 'sable', 'gujan-mestras': 'sauge', 'le-teich': 'sauge'};
Object.keys(PHOTO_INFO).forEach(function(k){ MOTIFS[k] = PHOTO_INFO[k].n; });
STEPS[2].p = 'Choisissez la photographie de couverture, la palette et la typographie de votre livret.';
function photoOf(k){ return PHOTOS[k] ? k : 'pinasse'; }

/* Nouveau livret : édition premium, palette et photo de la commune */
var _newCfgClassic = newCfg;
newCfg = function(a){
  var c = _newCfgClassic(a), k = c.commune;
  c.skin = 'premium'; c.theme.amb = PALETTE_FOR[k] || 'ivoire'; c.theme.font = 'lux'; c.theme.motif = COVER_FOR[k] || 'pinasse';
  return c;
};
/* Les photos voyagent avec la configuration envoyée au livret (aperçu, démo, fichier téléchargé), jamais dans la sauvegarde */
withMedia = function(c){
  if (!c || !c.theme) return c;
  var o = Object.assign({}, c), k = photoOf(c.theme.motif), b = BASSIN_FOR[c.commune] || 'passes';
  if (b === k) b = k === 'passes' ? 'arguin' : 'passes';
  var used = (c.theme.photo ? [] : [k]).concat([b]);
  o.skin = 'premium'; o.brand = BRAND.name;
  o._img = {hero: PHOTOS[k], bassin: PHOTOS[b], credit: 'Photographies : ' + used.map(function(x){ var i = PHOTO_INFO[x]; return i.n + ' © ' + i.a + ' (' + i.l + ')'; }).join(' · ') + ', via Wikimedia Commons.'};
  return o;
};
/* Partout où le studio montrait l'illustration (récapitulatif, espace client, affiche), la photo du Bassin */
var _sceneClassic = sceneSVG;
sceneSVG = function(o){
  var k = o && o.motif;
  if (k && PHOTOS[k]) return '<svg viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><image href="' + PHOTOS[k] + '" width="400" height="300" preserveAspectRatio="xMidYMid slice"/></svg>';
  return _sceneClassic(o);
};
(function(){ var st = document.createElement('style'); st.textContent = Object.keys(PHOTOS).map(function(k){ return '.phx-' + k + '{background-image:url(' + PHOTOS[k] + ')}'; }).join('\n'); document.head.appendChild(st); })();

/* Étape « Style » : photographies du Bassin, palettes, typographie */
var _drawStepClassic = drawStep;
drawStep = function(){
  if (ST.step !== 3) return _drawStepClassic();
  var c = ST.cfg, s = STEPS[2], cur = photoOf(c.theme.motif), h = '<div class="st-h"><h2>' + s.h + '</h2><p>' + s.p + '</p></div>';
  h += '<div class="lbl">Photographie de couverture</div><div class="covers">' + Object.keys(PHOTO_INFO).map(function(k){ return '<button data-cover="' + k + '" class="cov phx-' + k + (!c.theme.photo && cur === k ? ' on' : '') + '"><span>' + esc(PHOTO_INFO[k].n) + '</span></button>'; }).join('') + '</div>';
  h += '<div class="fld"><label class="drop">' + (c.theme.photo ? '<img src="' + c.theme.photo + '" alt="">' : '<span class="ph">+</span>') + '<span><b style="font-size:14.5px;font-weight:500">' + (c.theme.photo ? 'Changer votre photo' : 'Ou la photo de votre maison') + '</b><br><small style="color:var(--mut)">Elle remplace la photographie du Bassin en couverture. Ses couleurs vous seront proposées.</small></span><input type="file" accept="image/*" id="photoIn" hidden></label>' + (c.theme.photo ? '<button class="linkbtn" data-act="nophoto" style="margin-top:8px;font-size:13.5px">Revenir aux photos du Bassin</button>' : '') + '</div>';
  h += '<div class="lbl" style="margin-top:24px">Palette</div><div class="pals">' + LUX_THEMES.map(function(k){ var T = THEMES[k], L = T.light; return '<button data-amb="' + k + '" class="pal' + (c.theme.amb === k ? ' on' : '') + '"><span class="sw3"><i style="background:' + L.bg + '"></i><i style="background:' + L.text + '"></i><i style="background:' + L.acc + '"></i></span><b>' + esc(T.label) + '</b><small>' + esc(T.desc) + '</small></button>'; }).join('') + '</div>';
  var base = (THEMES[c.theme.amb] || THEMES.ivoire).light.acc, presets = [base, '#8F7447', '#1E3A57', '#4A6B60', '#946A42', '#6B4E5E', '#16191C'], ph = ST.photoColors || [];
  h += '<div class="fld"><label>Couleur d’accent</label><div class="sw">' + presets.concat(ph).filter(function(x, i, a){ return a.indexOf(x) === i; }).map(function(col, i){ var on = (c.theme.accent || base).toLowerCase() === col.toLowerCase(); return '<button style="background:' + col + '" data-accent="' + (i === 0 ? '' : col) + '" class="' + (on ? 'on' : '') + '" title="' + (i === 0 ? 'Couleur de la palette' : col) + '"></button>'; }).join('') + '<input type="color" id="accIn" value="' + (c.theme.accent || base) + '" title="Couleur personnalisée"></div>' + (ph.length ? '<div class="hint">Les dernières pastilles viennent de votre photo.</div>' : '') + '</div>';
  h += '<div class="two"><div class="fld"><label>Typographie</label><select class="in" data-b="theme.font">' + Object.keys(FONTS).map(function(k){ return '<option value="' + k + '"' + (c.theme.font === k ? ' selected' : '') + '>' + FONTS[k].label + (k === 'lux' ? ' (signature)' : '') + '</option>'; }).join('') + '</select></div>';
  h += '<div class="fld"><label>Jour / nuit</label><select class="in" data-b="theme.mode"><option value="auto"' + (c.theme.mode === 'auto' ? ' selected' : '') + '>Automatique (soleil)</option><option value="light"' + (c.theme.mode === 'light' ? ' selected' : '') + '>Toujours clair</option><option value="dark"' + (c.theme.mode === 'dark' ? ' selected' : '') + '>Toujours sombre</option></select></div></div>';
  h += '<div class="sigcard"><div class="sk">Offre Signature · sur mesure</div><b>Une maison d’exception mérite un livret unique.</b><p>Direction artistique exclusive, vos propres photographies, textes soignés en plusieurs langues, adresses et services haut de gamme, guides animés de vos équipements. 690 € la première année, puis 149 € par an.</p><div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap"><button class="btn sm" data-act="brief">Décrire mon projet</button><button class="gxlink" data-gx="clim">Voir un guide animé</button></div></div>';
  $('pBody').innerHTML = h; bindStep();
  qa('[data-cover]', $('pBody')).forEach(function(b){ b.addEventListener('click', function(){ ST.cfg.theme.motif = b.getAttribute('data-cover'); ST.cfg.theme.photo = ''; ST.photoColors = []; drawStep(); changed(); }); });
};

/* =================== Le concierge IA : il apprend des réponses de l'hôte =================== */
PLANS[1].name = 'Concierge IA'; PLANS[1].desc = '+ concierge IA qui apprend de vous';
STEPS[4].h = 'Votre concierge IA';
STEPS[4].p = 'Il connaît déjà le Bassin, les conditions et l’agenda du jour, et adapte ses idées à chaque voyageur. Votre part, c’est la maison : chaque réponse que vous lui apprenez, il la retient pour tous vos voyageurs.';
function learnedOf(c){ return ((c && c.faq) || []).filter(function(f){ return f.q && f.a; }); }
function learnedPill(c){ var n = learnedOf(c).length; return '<span class="lrn">' + (n ? n + ' réponse' + (n > 1 ? 's' : '') + ' apprise' + (n > 1 ? 's' : '') : 'Rien appris pour l’instant') + '</span>'; }
function learnBox(){
  return '<div class="learn"><div class="lk">Comment il apprend</div><ol>' +
    '<li><span><b>Un voyageur demande</b> ce que le concierge ne sait pas encore.</span></li>' +
    '<li><span><b>Il ne l’invente pas</b> : il le dit, propose de vous écrire et vous transmet la question.</span></li>' +
    '<li><span><b>Vous répondez une fois</b>, depuis votre espace client.</span></li>' +
    '<li><span><b>Il s’en souvient</b> pour tous les voyageurs suivants, dans leur langue.</span></li></ol>' +
    '<p>Vos voyageurs, eux, échangent avec « votre concierge » : il parle en votre nom, sait tout ce que vous lui avez appris et vous passe la main quand il le faut. Il se présente simplement comme votre assistant virtuel, comme le veut la loi.</p>' +
    '<p>Dans la version en ligne, les questions qu’il ignore arrivent sur votre téléphone et votre réponse s’ajoute ici toute seule. Vous pouvez aussi lui apprendre vos réponses dès maintenant.</p></div>';
}
function accLearnCard(a, ids){
  var h = '<div class="acc-card lrn-acc" style="margin-top:16px"><div class="k">Votre concierge IA</div><h3 style="font-size:26px;margin-top:8px">Il apprend de vos réponses</h3><p style="color:var(--ink2);margin:8px 0 0;font-size:14.5px">Quand un voyageur lui pose une question qu’il ne connaît pas, il ne l’invente pas : il vous la transmet. Vous répondez une fois, il s’en souvient pour tous les suivants.</p>';
  ids.forEach(function(id){
    var c = a.livrets[id].cfg, L = learnedOf(c);
    h += '<div class="lrn-row"><div class="lrn-h"><b>' + esc(c.name || 'Mon livret') + '</b>' + learnedPill(c) + '</div>' +
      (L.length ? '<ul>' + L.slice(0, 3).map(function(f){ return '<li><i>« ' + esc(f.q) + ' »</i>' + esc(f.a.length > 110 ? f.a.slice(0, 108) + '…' : f.a) + '</li>'; }).join('') + '</ul>' + (L.length > 3 ? '<div style="font-size:12.5px;color:var(--mut);margin-top:6px">et ' + (L.length - 3) + ' autre' + (L.length > 4 ? 's' : '') + '</div>' : '')
        : '<p style="font-size:13.5px;color:var(--mut);margin:8px 0 0">Il connaît déjà votre logement et le Bassin. Apprenez-lui vos réponses aux questions qu’on vous pose souvent.</p>') +
      '<button class="btn sm" style="margin-top:14px" data-teach="' + esc(id) + '">Lui apprendre une réponse</button></div>';
  });
  return h + '<p style="font-size:12.5px;color:var(--mut);margin:16px 0 0">Bientôt ici : les questions qu’il n’a pas su résoudre, à traiter en un geste.</p></div>';
}
