/* Vitrine : un extrait de l'agenda du Bassin, en direct */
function renderLandingAgenda(){
  var box = $('lAgenda'); if (!box) return;
  if (typeof AGENDA === 'undefined' || !AGENDA.ev || !AGENDA.ev.length){ box.closest('section').classList.add('hidden'); return; }
  var c = BASSIN.center, o = {lat: c.lat, lon: c.lon, km: 30}, all = agQuery(Object.assign({}, o, {from: agDay(), to: agAdd(agDay(), 30)})), hl = agHighlights(o, 10);
  var list = hl.filter(function(x){ return x.ev.i; }).slice(0, 4);  /* l'extrait montre de préférence des événements en photo */
  hl.concat(all.filter(function(x){ return x.ev.i; }), all).forEach(function(x){ if (list.length < 4 && list.every(function(y){ return y.ev !== x.ev; })) list.push(x); });
  list.sort(function(a, b){ return a.day - b.day; });
  box.innerHTML = list.map(function(x){ var ev = x.ev, cat = AG_CATS[(ev.k || ['autre'])[0]] || AG_CATS.autre, sd = agShort(x.day, 'fr'), d = ev.d || '';
    var L = agLink(ev), tag = L ? 'a' : 'div', attrs = L ? ' href="' + esc(L.href) + '" target="_blank" rel="noopener"' : '';
    var ph = /^https:\/\//.test(ev.i || '') ? '<div class="lagi"><img src="' + esc(ev.i) + '" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.parentNode.parentNode.classList.remove(\'ph\');this.parentNode.remove()"></div>' : '';
    return '<' + tag + ' class="lagc' + (ph ? ' ph' : '') + '"' + attrs + '>' + ph + '<div class="lagd"><small>' + esc(sd.dow) + '</small><b>' + sd.d + '</b><small>' + esc(sd.m) + '</small></div><div class="lagb"><div class="k">' + esc(cat.fr) + (ev.c ? ' · ' + esc(ev.c) : '') + '</div><b>' + esc(ev.n) + '</b>' + (d ? '<p>' + esc(d.length > 120 ? d.slice(0, 118).replace(/\s+\S*$/, '') + '…' : d) + '</p>' : '') + (L ? '<span class="lagl">' + (L.kind === 'page' ? 'En savoir plus' : L.kind === 'org' ? 'Site de l’événement' : 'Agenda de l’office de tourisme') + ' ↗</span>' : '') + '</div></' + tag + '>'; }).join('');
  var nn = $('lAgendaN'); if (nn) nn.textContent = all.length + ' événements dans les 30 prochains jours autour du Bassin · agenda des offices de tourisme (DATAtourisme), mis à jour le ' + agUpdated('fr') + '.';
}
